using DriveOS.Modules.Students.Domain.ExternalTransfers;using DriveOS.SharedKernel.Identifiers;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DriveOS.Modules.Students.Infrastructure.Persistence.Configurations;
internal sealed class ExternalTransferCaseConfiguration:IEntityTypeConfiguration<ExternalTransferCase>{public void Configure(EntityTypeBuilder<ExternalTransferCase>b){b.ToTable("external_transfer_cases");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").HasConversion(x=>x.Value,x=>new ExternalTransferCaseId(x)).ValueGeneratedNever();b.Property(x=>x.SourceOrganizationId).HasColumnName("source_organization_id").HasConversion(x=>x.Value,x=>new OrganizationId(x));b.Property(x=>x.TargetOrganizationId).HasColumnName("target_organization_id").HasConversion(x=>x.Value,x=>new OrganizationId(x));b.Property(x=>x.StudentId).HasColumnName("student_id").HasConversion(x=>x.Value,x=>new PersonId(x));b.Property(x=>x.Type).HasColumnName("transfer_type").HasConversion<string>().HasMaxLength(40);b.Property(x=>x.DataScope).HasColumnName("data_scope").HasConversion<long>();b.Property(x=>x.EffectiveOn).HasColumnName("effective_on");b.Property(x=>x.TemporaryUntil).HasColumnName("temporary_until");b.Property(x=>x.CountryCode).HasColumnName("country_code").HasMaxLength(3);b.Property(x=>x.Reason).HasColumnName("reason").HasMaxLength(1000);b.Property(x=>x.Responsibilities).HasColumnName("responsibilities").HasMaxLength(2000);b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(30);b.Property(x=>x.ConsentStatus).HasColumnName("consent_status").HasConversion<string>().HasMaxLength(30);b.Property(x=>x.ConsentEvidenceReference).HasColumnName("consent_evidence_reference").HasMaxLength(500);b.Property(x=>x.ConsentVerifiedAtUtc).HasColumnName("consent_verified_at_utc");b.Property(x=>x.FinancialStatus).HasColumnName("financial_status").HasConversion<string>().HasMaxLength(30);b.Property(x=>x.FinancialResolution).HasColumnName("financial_resolution").HasMaxLength(2000);b.Property(x=>x.RelationshipStatus).HasColumnName("relationship_status").HasConversion<string>().HasMaxLength(30);b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.CreatedByUserId).HasColumnName("created_by_user_id").HasConversion(x=>x.Value,x=>new UserId(x));b.Property(x=>x.CompletedAtUtc).HasColumnName("completed_at_utc");b.HasOne<DriveOS.Modules.Students.Domain.Students.Student>().WithMany().HasForeignKey(x=>x.StudentId).OnDelete(DeleteBehavior.Restrict);b.HasMany(x=>x.DataGrants).WithOne().HasForeignKey(x=>x.ExternalTransferCaseId).OnDelete(DeleteBehavior.Cascade);b.HasMany(x=>x.Audit).WithOne().HasForeignKey(x=>x.ExternalTransferCaseId).OnDelete(DeleteBehavior.Cascade);b.Navigation(x=>x.DataGrants).UsePropertyAccessMode(PropertyAccessMode.Field);b.Navigation(x=>x.Audit).UsePropertyAccessMode(PropertyAccessMode.Field);b.HasIndex(x=>new{x.SourceOrganizationId,x.StudentId,x.Status});b.Ignore(x=>x.DomainEvents);}}
internal sealed class StudentDataGrantConfiguration:IEntityTypeConfiguration<StudentDataGrant>{public void Configure(EntityTypeBuilder<StudentDataGrant>b){b.ToTable("student_data_grants");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").ValueGeneratedNever();b.Property(x=>x.ExternalTransferCaseId).HasColumnName("external_transfer_case_id").HasConversion(x=>x.Value,x=>new ExternalTransferCaseId(x));b.Property(x=>x.GranteeOrganizationId).HasColumnName("grantee_organization_id").HasConversion(x=>x.Value,x=>new OrganizationId(x));b.Property(x=>x.Scope).HasColumnName("data_scope").HasConversion<long>();b.Property(x=>x.GrantedAtUtc).HasColumnName("granted_at_utc");b.Property(x=>x.ExpiresOn).HasColumnName("expires_on");b.Property(x=>x.RevokedAtUtc).HasColumnName("revoked_at_utc");b.HasIndex(x=>new{x.GranteeOrganizationId,x.ExpiresOn});}}
internal sealed class ExternalTransferAuditEntryConfiguration:IEntityTypeConfiguration<ExternalTransferAuditEntry>{public void Configure(EntityTypeBuilder<ExternalTransferAuditEntry>b){b.ToTable("external_transfer_audit_entries");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").ValueGeneratedNever();b.Property(x=>x.ExternalTransferCaseId).HasColumnName("external_transfer_case_id").HasConversion(x=>x.Value,x=>new ExternalTransferCaseId(x));b.Property(x=>x.Action).HasColumnName("action").HasMaxLength(60);b.Property(x=>x.Detail).HasColumnName("detail").HasMaxLength(2000);b.Property(x=>x.ActorUserId).HasColumnName("actor_user_id").HasConversion(x=>x.Value,x=>new UserId(x));b.Property(x=>x.OccurredAtUtc).HasColumnName("occurred_at_utc");b.HasIndex(x=>new{x.ExternalTransferCaseId,x.OccurredAtUtc});}}
